# originals-based transforms for None entries
def from_orig(page,a,b,fixes,cls='p'):
    y0,y1,L=find_para2(page,a,b); h=pedit.to_html(pedit.runs(L))
    for o,n in fixes:
        assert o in h,(a,o); h=h.replace(o,n)
    assert '<ph>' not in h,(a,h)
    return h
log=[]
