    pn,a,b=key[:3]; cls=key[3] if len(key)>3 else 'p'
    page=d[pn-1]
    y0,y1,L=find_para2(page,a,b)
    if html is None:
        if pn==8: html=from_orig(page,a,b,[('4.1%로올라갔다','4.1%로 올라갔다'),('집계 시점에 따라 64~70%로 반영돼 있다 <ph>발간 직전 갱신</ph>.','9월 29일 기준 집계에 따라 68~77%로 반영돼 있다.'),('있다.10월','있다. 10월')])
        elif pn==11: html=from_orig(page,a,b,[('60일선을 회복했다 <ph>9월 말 60일·120일선위치 확인</ph>.','60일선을 회복했으나, 28일부터 30일까지 사흘 연속 하락해 30일 6,838.04로 마감했다.')])
